package com.example.byokchat.youtube

/**
 * Subtitle track selection + WebVTT -> SRT (YouTube tools, 2026-11-13).
 * Pure Kotlin, no Android, no network.
 *
 * Locked rule (Duy, 2026-11-13): the goal is to get whatever transcript is
 * available — language is only a hint. NewPipeExtractor's
 * getSubtitlesDefault() reads only captionTracks; auto-translated tracks
 * are NOT returned (its source has an unused TODO for translationLanguages),
 * so the chain below only ever sees manual / auto-generated tracks.
 *
 * Selection order, done by the app (never by the AI):
 *  1. manual in the requested language (if the user named one),
 *  2. auto-generated in the requested language,
 *  3. manual in the original language,
 *  4. auto-generated in the original language,
 *  5. manual in Vietnamese, then English,
 *  6. auto-generated in Vietnamese, then English,
 *  7. any manual track, then any auto-generated track (something beats nothing).
 * The extractor does not tell us the video's spoken language, so steps 3-4
 * use the tracks that are neither Vietnamese nor English, in the order
 * YouTube returned them (captionTracks list the original language first).
 */

/** One subtitle track as NewPipeExtractor reports it. */
data class SubtitleTrack(
    val languageTag: String,
    val isAutoGenerated: Boolean,
    val displayLanguageName: String,
    val contentUrl: String,
)

/** Primary language subtag, lower-cased: "en-US" -> "en", "vi_VN" -> "vi". */
fun primaryLanguage(tag: String): String =
    tag.trim().lowercase().split('-', '_').firstOrNull().orEmpty()

private fun matchesLanguage(track: SubtitleTrack, language: String): Boolean {
    val want = primaryLanguage(language)
    return want.isNotEmpty() && primaryLanguage(track.languageTag) == want
}

/** Pick the best track, or null when the video has no subtitles at all. */
fun selectSubtitleTrack(tracks: List<SubtitleTrack>, preferredLanguage: String?): SubtitleTrack? {
    if (tracks.isEmpty()) return null
    val manual = tracks.filter { !it.isAutoGenerated }
    val auto = tracks.filter { it.isAutoGenerated }
    if (!preferredLanguage.isNullOrBlank()) {
        manual.firstOrNull { matchesLanguage(it, preferredLanguage) }?.let { return it }
        auto.firstOrNull { matchesLanguage(it, preferredLanguage) }?.let { return it }
    }
    // Original language: a track that is neither Vietnamese nor English.
    manual.firstOrNull { primaryLanguage(it.languageTag) !in setOf("vi", "en") }?.let { return it }
    auto.firstOrNull { primaryLanguage(it.languageTag) !in setOf("vi", "en") }?.let { return it }
    manual.firstOrNull { matchesLanguage(it, "vi") }?.let { return it }
    manual.firstOrNull { matchesLanguage(it, "en") }?.let { return it }
    auto.firstOrNull { matchesLanguage(it, "vi") }?.let { return it }
    auto.firstOrNull { matchesLanguage(it, "en") }?.let { return it }
    return manual.firstOrNull() ?: auto.firstOrNull()
}

/** Suffix for a downloaded transcript file: "en" for manual, "en-auto" for auto-generated. */
fun subtitleFileSuffix(track: SubtitleTrack): String =
    primaryLanguage(track.languageTag).ifBlank { "unknown" } +
        if (track.isAutoGenerated) "-auto" else ""

private val VTT_TIMESTAMP = Regex("""(\d{1,2}:)?(\d{1,2}):(\d{2})[.,](\d{3})""")

private fun vttTimeToSrt(raw: String): String? {
    val m = VTT_TIMESTAMP.matchEntire(raw.trim()) ?: return null
    val (h, min, sec, ms) = m.destructured
    val hours = h.removeSuffix(":").toIntOrNull() ?: 0
    return "%02d:%02d:%02d,%s".format(hours, min.toInt(), sec.toInt(), ms)
}

private fun stripVttMarkup(text: String): String = text
    .replace(Regex("<[^>]*>"), "")
    .replace("&amp;", "&").replace("&lt;", "<").replace("&gt;", ">")
    .replace("&quot;", "\"").replace("&#39;", "'").replace("&nbsp;", " ")
    .trim()

/**
 * WebVTT -> SRT. Skips the WEBVTT header, NOTE / STYLE / REGION blocks and
 * cue settings after the timestamps. Returns "" when no cues were found.
 */
fun webVttToSrt(vtt: String): String {
    val lines = vtt.lines()
    val cues = mutableListOf<Triple<String, String, String>>() // start, end, text
    var i = 0
    while (i < lines.size) {
        val line = lines[i].trim()
        if (line.isEmpty() || line.startsWith("WEBVTT") || line.startsWith("NOTE") ||
            line == "STYLE" || line == "REGION"
        ) {
            i++
            continue
        }
        // A cue id line (no "-->") is followed by its timestamp line.
        val tsLine = if (line.contains("-->")) line else lines.getOrNull(i + 1)?.trim().orEmpty()
        if (!tsLine.contains("-->")) {
            i++
            continue
        }
        val parts = tsLine.split("-->").map { it.trim() }
        val start = vttTimeToSrt(parts[0].substringBefore(' '))
        val end = vttTimeToSrt(parts.getOrNull(1)?.substringBefore(' ') ?: "")
        if (start == null || end == null) {
            i++
            continue
        }
        val textLines = mutableListOf<String>()
        var j = if (line.contains("-->")) i + 1 else i + 2
        while (j < lines.size && lines[j].isNotBlank()) {
            textLines += stripVttMarkup(lines[j])
            j++
        }
        val text = textLines.filter { it.isNotBlank() }.joinToString("\n")
        if (text.isNotBlank()) cues += Triple(start, end, text)
        i = j
    }
    return cues.mapIndexed { index, (start, end, text) ->
        "${index + 1}\n$start --> $end\n$text"
    }.joinToString("\n\n") + if (cues.isEmpty()) "" else "\n"
}
